INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=17 AND status='published'),'destination','Australia',NULL,'<p>Strong hospitality training with placement options.</p><p>Student visa fee is AUD 2,500 from 1 July 2026 and the national planning level is 295,000 new international students (kept for 2027). Graduates can apply for the Temporary Graduate visa (485); length depends on qualification and region.</p>','published',4,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=17 AND status='published') AND name='Restaurant Management'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=17 AND status='published'),'destination','Canada',NULL,'<p>College and university programmes in culinary arts and hospitality.</p><p>Post-Graduation Work Permit of up to 3 years for eligible programmes (degree graduates are exempt from the field-of-study list). Study permits are capped nationally (408,000 for 2026), but master''s and doctoral students at public institutions are exempt from the cap from 1 January 2026.</p>','published',5,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=17 AND status='published') AND name='Restaurant Management'));
