INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=19 AND status='published'),'about','About Maritime Studies',NULL,'<p>Maritime Studies focuses on shipping, ports, safety and the maritime industry. It sits within Maritime &amp; Shipping and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=19 AND status='published') AND name='Maritime Studies'));
