INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=20 AND status='published'),'why','Why study Screenwriting?',NULL,'<p>Screenwriting builds specialist skills in writing for film, TV and streaming. Typical graduate roles include screenwriter, script editor, story analyst. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND name='Screenwriting'));
