BEGIN;
-- ===== Subject 16: Fashion & Textiles
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published');
UPDATE subjects SET about_title='About Fashion & Textiles', about_body='<p>Fashion and Textiles covers design, technology, business and communication in the clothing, footwear, accessories and fabric industries.</p><p>Courses include fashion design, buying and merchandising, marketing, styling, textile science, apparel technology and sustainability. Many programmes expect a portfolio at application and include industry placements and graduate showcases.</p><p>Studying in a fashion capital gives access to brands, studios, trade shows and networks.</p>', why_title='Why study Fashion & Textiles?', why_body='<p><strong>Creative and commercial.</strong> You combine design with business, technology and communication.</p><p><strong>Industry connections.</strong> Fashion hubs offer internships, brand collaborations and graduate shows.</p><p><strong>Growing focus on sustainability.</strong> Ethical sourcing, circular design and traceability are creating new roles.</p><p><strong>Varied careers.</strong> Graduates become designers, buyers, merchandisers, stylists, technologists, marketers and journalists.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=16 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Fashion & Textiles', about_body='<p>A Foundation in Fashion &amp; Textiles. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Fashion & Textiles?', why_body='<p>Foundation study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Fashion & Textiles', about_body='<p>A Pathway in Fashion &amp; Textiles. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Fashion & Textiles?', why_body='<p>Pathway study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Fashion & Textiles', about_body='<p>A Diploma in Fashion &amp; Textiles. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Fashion & Textiles?', why_body='<p>Diploma study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Fashion & Textiles', about_body='<p>A Bachelor''s in Fashion &amp; Textiles. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Fashion & Textiles?', why_body='<p>Bachelor''s study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Fashion & Textiles', about_body='<p>A Master''s in Fashion &amp; Textiles. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Fashion & Textiles?', why_body='<p>Master''s study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Fashion & Textiles', about_body='<p>A MBA in Fashion &amp; Textiles. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Fashion & Textiles?', why_body='<p>MBA study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Fashion & Textiles', about_body='<p>A PhD in Fashion &amp; Textiles. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Fashion & Textiles?', why_body='<p>PhD study in Fashion &amp; Textiles lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=16 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
-- ===== Subject 17: Hospitality, Culinary & Food
