UPDATE subjects SET about_title='About Media, Entertainment & Gaming', about_body='<p>Media, Entertainment and Gaming covers film, television, animation, visual effects, game design and development, esports, music production and business, theatre and performing arts.</p><p>Courses are project-based: you build a portfolio or showreel through productions, studio work and industry briefs. Many ask for a portfolio or audition at application.</p><p>Studying near production hubs gives access to studios, games companies, broadcasters and festivals.</p>', why_title='Why study Media, Entertainment & Gaming?', why_body='<p><strong>Creative industries are growing.</strong> Streaming, games and digital content are large, international markets.</p><p><strong>Portfolio-led learning.</strong> You graduate with work to show employers.</p><p><strong>Technical and creative roles.</strong> Programming, art, audio, production and business roles all exist.</p><p><strong>Freelance and studio routes.</strong> Many careers combine project work and permanent roles.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=20 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Media, Entertainment & Gaming', about_body='<p>A Foundation in Media, Entertainment &amp; Gaming. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Media, Entertainment & Gaming?', why_body='<p>Foundation study in Media, Entertainment &amp; Gaming lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
