UPDATE subject_study_levels SET about_title='About Diploma in Media, Entertainment & Gaming', about_body='<p>A Diploma in Media, Entertainment &amp; Gaming. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Media, Entertainment & Gaming?', why_body='<p>Diploma study in Media, Entertainment &amp; Gaming lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Media, Entertainment & Gaming', about_body='<p>A Bachelor''s in Media, Entertainment &amp; Gaming. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Media, Entertainment & Gaming?', why_body='<p>Bachelor''s study in Media, Entertainment &amp; Gaming lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Media, Entertainment & Gaming', about_body='<p>A Master''s in Media, Entertainment &amp; Gaming. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Media, Entertainment & Gaming?', why_body='<p>Master''s study in Media, Entertainment &amp; Gaming lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Media, Entertainment & Gaming', about_body='<p>A MBA in Media, Entertainment &amp; Gaming. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Media, Entertainment & Gaming?', why_body='<p>MBA study in Media, Entertainment &amp; Gaming lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Media, Entertainment & Gaming', about_body='<p>A PhD in Media, Entertainment &amp; Gaming. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Media, Entertainment & Gaming?', why_body='<p>PhD study in Media, Entertainment &amp; Gaming lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=20 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
COMMIT;